const d = $input.first().json;
// ===== Resolver fecha de forma determinista (mismo motor que voz) =====
function resolverFecha(input) {
  if (!input) return '';
 let s = String(input).trim().toLowerCase();
  const numLetra = {una:1,uno:1,un:1,dos:2,tres:3,cuatro:4,cinco:5,seis:6,siete:7,ocho:8,nueve:9,diez:10};
  for (const [pal, n] of Object.entries(numLetra)) {
    s = s.replace(new RegExp('\\b' + pal + '\\b', 'g'), String(n));
  }
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const ahora = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Madrid' }));
  const hoy = new Date(ahora.getFullYear(), ahora.getMonth(), ahora.getDate());
  const fmt = (x) => {
    const y = x.getFullYear();
    const m = String(x.getMonth() + 1).padStart(2, '0');
    const dd = String(x.getDate()).padStart(2, '0');
    return `${y}-${m}-${dd}`;
  };
  let m = s.match(/\b(\d{1,2})[\/\-](\d{1,2})(?:[\/\-](\d{2,4}))?\b/);
  if (m) {
    const dd = parseInt(m[1], 10);
    const mm = parseInt(m[2], 10);
    let yyyy = m[3] ? parseInt(m[3], 10) : hoy.getFullYear();
    if (yyyy < 100) yyyy += 2000;
    let cand = new Date(yyyy, mm - 1, dd);
    if (!m[3] && cand < hoy) cand = new Date(yyyy + 1, mm - 1, dd);
    if (!isNaN(cand)) return fmt(cand);
  }
  if (s.includes('hoy')) return fmt(hoy);
  if (s.includes('pasado manana') || s.includes('pasado mañana')) {
    const x = new Date(hoy); x.setDate(x.getDate() + 2); return fmt(x);
  }
  if (s.includes('manana') || s.includes('mañana')) {
    const x = new Date(hoy); x.setDate(x.getDate() + 1); return fmt(x);
  }
  m = s.match(/(?:en|dentro de)\s+(\d+)\s*d[ií]as?/);
  if (m) { const x = new Date(hoy); x.setDate(x.getDate() + parseInt(m[1], 10)); return fmt(x); }
  m = s.match(/(?:en|dentro de)\s+(\d+)\s*semanas?/);
  if (m) { const x = new Date(hoy); x.setDate(x.getDate() + parseInt(m[1], 10) * 7); return fmt(x); }
  if (s.includes('semana que viene') || s.includes('proxima semana') || s.includes('próxima semana') || s.includes('semana proxima') || s.includes('semana próxima')) {
    const x = new Date(hoy); x.setDate(x.getDate() + 7); return fmt(x);
  }
  const dias = {'domingo':0,'lunes':1,'martes':2,'miercoles':3,'miércoles':3,'jueves':4,'viernes':5,'sabado':6,'sábado':6};
  for (const [nombre, num] of Object.entries(dias)) {
    if (s.includes(nombre)) {
      const x = new Date(hoy);
      let diff = (num - x.getDay() + 7) % 7;
      if (diff === 0) diff = 7;
      x.setDate(x.getDate() + diff);
      return fmt(x);
    }
  }

  // ===== NUEVO: numero de dia del mes suelto: "12", "el 12", "el dia 20", "el 12 de este mes" =====
  m = s.match(/\b(\d{1,2})\b/);
  if (m) {
    const dia = parseInt(m[1], 10);
    if (dia >= 1 && dia <= 31) {
      let cand = new Date(hoy.getFullYear(), hoy.getMonth(), dia);
      if (cand < hoy) cand = new Date(hoy.getFullYear(), hoy.getMonth() + 1, dia);
      if (!isNaN(cand) && cand.getDate() === dia) return fmt(cand);
    }
  }

  return '';
}
const fechaResuelta = resolverFecha(d.fecha);
const fechaNuevaResuelta = resolverFecha(d.fecha_nueva);
const fechaHastaResuelta = resolverFecha(d.fecha_hasta);
return [{ json: {
  fn:          d.fn ?? '',
