const d = $input.first().json;
if (!d.servicio_nombre) {
  return [{ json: { response: 'NO_SERVICIO: No tenemos ese servicio. ¿Quiere otra cosa?' } }];
}
const fechaStr = $('1. Resolver fecha').first().json.fecha;
if (!fechaStr) {
  return [{ json: { response: 'Necesito saber para qué día. ¿Qué día le viene bien?' } }];
}

// ===== CAPACIDAD POR NEGOCIO (reservas simultáneas; quien no esté aquí = 1, comportamiento de siempre) =====
const CAPACIDAD = {
  '8d0ce837-82a2-4d0f-bf55-95d581d7d680': 10,   // La Tasqueta · mesas simultáneas << EDITAR si Quique da otra cifra >>
};
// ===== NEGOCIOS CON FRANJAS DE RESTAURANTE (mediodía/noche, corte 18h) =====
const RESTAURANTE = new Set([
  '8d0ce837-82a2-4d0f-bf55-95d581d7d680',       // La Tasqueta
]);
const negocioId = $('1. Resolver fecha').first().json.negocio_id || '';
const cap = CAPACIDAD[negocioId] ?? 1;
const esRestaurante = RESTAURANTE.has(negocioId);

const fecha = new Date(fechaStr + 'T00:00:00');
const diasMap = ['dom','lun','mar','mie','jue','vie','sab'];
const diaKey = diasMap[fecha.getDay()];
const nombresDia = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const horario = typeof d.horario_negocio === 'string' ? JSON.parse(d.horario_negocio) : (d.horario_negocio || {});
const tramoDia = horario[diaKey];
if (!tramoDia || tramoDia === 'cerrado') {
  for (let i = 1; i <= 7; i++) {
    const f2 = new Date(fecha); f2.setDate(f2.getDate() + i);
    const k = diasMap[f2.getDay()];
    if (horario[k] && horario[k] !== 'cerrado') {
      return [{ json: { response: 'CERRADO: Ese día está cerrado. El siguiente día que abrimos es el ' + nombresDia[f2.getDay()] + '. ¿Quiere que mire ese día?' } }];
    }
  }
  return [{ json: { response: 'CERRADO: Ese día está cerrado.' } }];
}
// Duración del servicio pedido
const dur = d.duracion || 30;
// Citas ocupadas como INTERVALOS en minutos (ini y fin)
const toMin = (s) => { const [h,m] = s.slice(0,5).split(':').map(Number); return h*60 + m; };
const ocupadas = (d.ocupadas || []).map(o => ({ ini: toMin(o.ini), fin: toMin(o.fin) }));
// ===== NUEVO: si piden HOY, descartar horas ya pasadas =====
const ahoraTZ = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Madrid' }));
const hoyStr = ahoraTZ.getFullYear() + '-' + String(ahoraTZ.getMonth()+1).padStart(2,'0') + '-' + String(ahoraTZ.getDate()).padStart(2,'0');
const esHoy = (fechaStr === hoyStr);
const minAhora = ahoraTZ.getHours() * 60 + ahoraTZ.getMinutes();
// Generar slots: un slot cae SOLO cuando las reservas que solapan alcanzan la capacidad
const slots = [];
for (const tramo of tramoDia.split(',')) {
  const [ini, fin] = tramo.split('-').map(Number);
  for (let m = ini * 60; m + dur <= fin * 60; m += 30) {
    if (esHoy && m <= minAhora) continue;   // hora ya pasada hoy
    const slotFin = m + dur;
    const solapan = ocupadas.filter(o => m < o.fin && slotFin > o.ini).length;
    if (solapan < cap) {
      const hh = String(Math.floor(m / 60)).padStart(2, '0');
      const mm = String(m % 60).padStart(2, '0');
      slots.push(`${hh}:${mm}`);
    }
  }
}
if (slots.length === 0) {
  const msg = esRestaurante
    ? 'SIN_HUECOS: No quedan mesas libres ese día. ¿Quiere que mire otro día?'
    : 'SIN_HUECOS: No quedan huecos libres ese día. ¿Quiere que mire otro día?';
  return [{ json: { response: msg } }];
}
// Agrupar en franjas: restaurante = mediodía/noche (corte 18h) · resto = mañana/tarde (corte 14h)
const corte  = esRestaurante ? 18 : 14;
const lblA   = esRestaurante ? '*Mediodía:*' : '*Por la mañana:*';
const lblB   = esRestaurante ? '*Por la noche:*' : '*Por la tarde:*';
const grupoA = slots.filter(s => parseInt(s.slice(0,2),10) < corte);
const grupoB = slots.filter(s => parseInt(s.slice(0,2),10) >= corte);
const fmt = (arr) => arr.map(s => s + 'h').join(', ');
let partes = [];
if (grupoA.length) partes.push(lblA + ' ' + fmt(grupoA));
if (grupoB.length) partes.push(lblB + ' ' + fmt(grupoB));
const intro = esRestaurante
  ? 'Para una ' + String(d.servicio_nombre).toLowerCase() + ' el ' + nombresDia[fecha.getDay()] + ' tengo:'
  : 'Para ' + d.servicio_nombre + ' el ' + nombresDia[fecha.getDay()] + ' tengo estos huecos:';
const cierre = esRestaurante ? '¿A qué hora les va bien?' : '¿Cuál prefieres?';
const texto = intro + '\n\n' + partes.join('\n') + '\n\n' + cierre;
return [{ json: { response: texto } }];
